// 站内信（系统定向通知）内容解析与跳转目标解析。
//
// 后端把通知内容以 JSON 字符串写进 message.content，前端消息页解析后渲染纯文本 + 跳转链接。
// 这里只做「解析」与「跳转目标归一化」，不依赖 vue-router，便于单测；
// 真正的路由跳转由调用方完成：讨论通知按路径跳讨论详情，判题通知复用
// util/router.ts 的 handleGotoJudgeJob（比赛提交 / 普通提交自动分流）。

/** 讨论通知的三种类型（历史类型，保持向后兼容） */
export const DISCUSSION_NOTIFICATION_TYPES = [
  "discuss_post_commented",
  "discuss_comment_replied",
  "discuss_reply_replied",
] as const;

/** 讨论通知类型 */
export type DiscussionNotificationType = (typeof DISCUSSION_NOTIFICATION_TYPES)[number];

/** 重判结果变更通知类型（content 契约见 docs 设计文档 §4） */
export const JUDGE_RESULT_CHANGED_NOTIFICATION_TYPE = "judge_result_changed";

/** 讨论相关通知内容 */
export interface DiscussionNotificationContent {
  type: DiscussionNotificationType;
  text: string;
  discuss_id: number;
  comment_id: number;
}

/** 重判结果变更通知内容 */
export interface JudgeResultChangedNotificationContent {
  type: typeof JUDGE_RESULT_CHANGED_NOTIFICATION_TYPE;
  text: string;
  /** 提交（judge_job）ID */
  judge_id: number;
  /** 比赛 ID；0 表示非比赛提交（契约允许缺省，解析时归一化为 0） */
  contest_id: number;
}

/** 系统定向通知内容（解析成功后的判别联合） */
export type NotificationContent =
  | DiscussionNotificationContent
  | JudgeResultChangedNotificationContent;

/** 通知点击后的跳转目标 */
export type NotificationLinkTarget =
  | { kind: "discussion"; location: string }
  | { kind: "judge"; judgeId: string; contestId: number | undefined };

/** 把未知值归一化为非负整数，不合法时回落 fallback（0） */
const toNonNegativeInt = (value: unknown, fallback = 0): number => {
  return typeof value === "number" && Number.isInteger(value) && value >= 0 ? value : fallback;
};

/** 判断是否为讨论通知类型 */
const isDiscussionNotificationType = (type: string): type is DiscussionNotificationType => {
  return (DISCUSSION_NOTIFICATION_TYPES as readonly string[]).includes(type);
};

/**
 * 解析系统定向通知内容，失败（非法 JSON / 未知类型 / 关键字段不合法）返回 null。
 *
 * 讨论通知的解析口径与历史实现保持一致：只要有 type/text 就认，
 * discuss_id 缺失只会导致「不可点击」，不会让整条通知退化成原始 JSON 文本。
 */
export function parseNotificationContent(content: string): NotificationContent | null {
  let parsed: unknown;
  try {
    parsed = JSON.parse(content);
  } catch {
    // 非合法 JSON，忽略
    return null;
  }
  if (!parsed || typeof parsed !== "object") {
    return null;
  }
  const record = parsed as Record<string, unknown>;
  if (typeof record.type !== "string" || typeof record.text !== "string") {
    return null;
  }

  if (isDiscussionNotificationType(record.type)) {
    return {
      type: record.type,
      text: record.text,
      discuss_id: toNonNegativeInt(record.discuss_id),
      comment_id: toNonNegativeInt(record.comment_id),
    };
  }

  if (record.type === JUDGE_RESULT_CHANGED_NOTIFICATION_TYPE) {
    // judge_id 是「查看提交」链接的必要条件，缺失时按无法解析处理
    const judgeId = toNonNegativeInt(record.judge_id);
    if (judgeId <= 0) {
      return null;
    }
    return {
      type: JUDGE_RESULT_CHANGED_NOTIFICATION_TYPE,
      text: record.text,
      judge_id: judgeId,
      contest_id: toNonNegativeInt(record.contest_id),
    };
  }

  return null;
}

/**
 * 解析通知的跳转目标，null 表示该通知不可跳转。
 *
 * 判题通知返回归一化后的 contestId：契约里 contest_id 为 0 / 缺省都表示非比赛提交，
 * 统一折成 undefined，调用方直接透传给 handleGotoJudgeJob 即可正确分流。
 */
export function resolveNotificationLink(
  notification: NotificationContent
): NotificationLinkTarget | null {
  if (notification.type === JUDGE_RESULT_CHANGED_NOTIFICATION_TYPE) {
    return {
      kind: "judge",
      judgeId: String(notification.judge_id),
      contestId: notification.contest_id > 0 ? notification.contest_id : undefined,
    };
  }
  if (!notification.discuss_id) {
    return null;
  }
  const hash = notification.comment_id ? `#comment-${notification.comment_id}` : "";
  return { kind: "discussion", location: `/discuss/${notification.discuss_id}${hash}` };
}

/** 通知卡片上「查看」链接的文案 */
export function notificationLinkText(notification: NotificationContent): string {
  return notification.type === JUDGE_RESULT_CHANGED_NOTIFICATION_TYPE ? "查看提交" : "点击查看";
}
